-- Lot 11.5 cleanup. Run start: 2026-10-06 07:12:31.789409+00.
-- Bounded by the fixed fixture UUIDs (coach B user/coach, its exercise, the 3 platform templates) and, for
-- what coach A created through the API, by COACH_ID/PROGRAM_TEMPLATE_COACH_ID = coach A AND created after the
-- run start. AUTH_OTPS / AUTH_REFRESH_TOKENS of coach A and of the member are kept (accounts used);
-- those of the fixture user l115-coachb are removed with it.
-- Dry run and commit versions of this file differ only by their last line (ROLLBACK / COMMIT).
\set ON_ERROR_STOP on
BEGIN;

\echo '--- rows that will be removed (before)'
SELECT 'AUTH_OTPS (l115 user)' AS tbl, count(*) FROM "AUTH_OTPS" WHERE "USER_ID" = '11500000-0000-4000-8000-0000000000b1'
UNION ALL SELECT 'AUTH_REFRESH_TOKENS (l115 user)', count(*) FROM "AUTH_REFRESH_TOKENS" WHERE "USER_ID" = '11500000-0000-4000-8000-0000000000b1'
UNION ALL SELECT 'COACH_PARAMETERS (coach B)', count(*) FROM "COACH_PARAMETERS" WHERE "COACH_ID" = '11500000-0000-4000-8000-0000000000b2'
UNION ALL SELECT 'OFFER_PROGRAMS (coach B)', count(*) FROM "OFFER_PROGRAMS" WHERE "COACH_ID" = '11500000-0000-4000-8000-0000000000b2'
UNION ALL SELECT 'EXERCISES (coach B)', count(*) FROM "EXERCISES" WHERE "EXERCISE_ID" = '11500000-0000-4000-8000-0000000000e1'
UNION ALL SELECT 'SESSION_TEMPLATES (3 fixtures)', count(*) FROM "SESSION_TEMPLATES" WHERE "SESSION_TEMPLATE_ID" IN ('11500000-0000-4000-8000-0000000000a1','11500000-0000-4000-8000-0000000000a2','11500000-0000-4000-8000-0000000000a3')
UNION ALL SELECT 'SESSION_TEMPLATES (coach A, after run start)', count(*) FROM "SESSION_TEMPLATES" WHERE "COACH_ID" = (SELECT c."COACH_ID" FROM "COACHES" c JOIN "USERS" u ON u."USER_ID" = c."USER_ID" WHERE u."USER_EMAIL" = 'coach@mentora.fr') AND "SESSION_TEMPLATE_CREATED_DATE" > '2026-10-06 07:12:31.789409+00'
UNION ALL SELECT 'PROGRAM_TEMPLATES (coach A, after run start)', count(*) FROM "PROGRAM_TEMPLATES" WHERE "PROGRAM_TEMPLATE_COACH_ID" = (SELECT c."COACH_ID" FROM "COACHES" c JOIN "USERS" u ON u."USER_ID" = c."USER_ID" WHERE u."USER_EMAIL" = 'coach@mentora.fr') AND "PROGRAM_TEMPLATE_CREATED_DATE" > '2026-10-06 07:12:31.789409+00'
UNION ALL SELECT 'COACHES (coach B)', count(*) FROM "COACHES" WHERE "COACH_ID" = '11500000-0000-4000-8000-0000000000b2'
UNION ALL SELECT 'USERS (l115 user)', count(*) FROM "USERS" WHERE "USER_ID" = '11500000-0000-4000-8000-0000000000b1';

\echo '--- deletes (rows removed per statement)'
DELETE FROM "SESSION_TEMPLATES" WHERE "SESSION_TEMPLATE_ID" IN ('11500000-0000-4000-8000-0000000000a1','11500000-0000-4000-8000-0000000000a2','11500000-0000-4000-8000-0000000000a3');
DELETE FROM "SESSION_TEMPLATES" WHERE "COACH_ID" = (SELECT c."COACH_ID" FROM "COACHES" c JOIN "USERS" u ON u."USER_ID" = c."USER_ID" WHERE u."USER_EMAIL" = 'coach@mentora.fr') AND "SESSION_TEMPLATE_CREATED_DATE" > '2026-10-06 07:12:31.789409+00';
DELETE FROM "PROGRAM_TEMPLATES" WHERE "PROGRAM_TEMPLATE_COACH_ID" = (SELECT c."COACH_ID" FROM "COACHES" c JOIN "USERS" u ON u."USER_ID" = c."USER_ID" WHERE u."USER_EMAIL" = 'coach@mentora.fr') AND "PROGRAM_TEMPLATE_CREATED_DATE" > '2026-10-06 07:12:31.789409+00';
DELETE FROM "EXERCISES" WHERE "EXERCISE_ID" = '11500000-0000-4000-8000-0000000000e1';
DELETE FROM "OFFER_PROGRAMS" WHERE "COACH_ID" = '11500000-0000-4000-8000-0000000000b2';
DELETE FROM "COACH_PARAMETERS" WHERE "COACH_ID" = '11500000-0000-4000-8000-0000000000b2';
DELETE FROM "COACHES" WHERE "COACH_ID" = '11500000-0000-4000-8000-0000000000b2';
DELETE FROM "AUTH_OTPS" WHERE "USER_ID" = '11500000-0000-4000-8000-0000000000b1';
DELETE FROM "AUTH_REFRESH_TOKENS" WHERE "USER_ID" = '11500000-0000-4000-8000-0000000000b1';
DELETE FROM "USERS" WHERE "USER_ID" = '11500000-0000-4000-8000-0000000000b1';

\echo '--- state inside the transaction after the deletes'
SELECT (SELECT count(*) FROM "SESSION_TEMPLATES") AS session_templates,
       (SELECT count(*) FROM "USERS" WHERE "USER_EMAIL" LIKE 'l115-%') AS l115_users,
       (SELECT count(*) FROM "EXERCISES" WHERE "EXERCISE_NAME" LIKE 'l115-%') AS l115_exercises,
       (SELECT count(*) FROM "PROGRAM_TEMPLATES" WHERE "PROGRAM_TEMPLATE_NAME" LIKE 'l115-%') AS l115_program_templates;

ROLLBACK;
